from pathlib import Path
import hashlib
import json
import os
import re
import unicodedata

import numpy as np
import pandas as pd

RAW_FILENAME = "TURNI FCIE BO CITTA 2026_verificato(53 SETT dal 36°).csv"
ACCESS_MODE_MEANING = {"P": "open-door", "C": "call/closed-door"}


INPUT_DIR = Path("data")
OUTPUT_DIR = Path("output")
OUTPUT_DIR.mkdir(exist_ok=True)


try:
    from google.colab import files
    IN_COLAB = True
except ImportError:
    files = None
    IN_COLAB = False


def require(condition, message):
    '''Fail loudly on a broken structural assumption rather than silently continuing.'''
    if not bool(condition):
        raise ValueError(message)


def resolve_csv(env_name, expected_name):
    configured = os.environ.get(env_name)
    candidates = [Path(configured)] if configured else []
    candidates += [
        Path(expected_name), INPUT_DIR / expected_name, Path("../data") / expected_name,
        Path("/content") / expected_name,
    ]
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    if IN_COLAB:
        uploaded = files.upload()
        csv_names = [name for name in uploaded if name.lower().endswith(".csv")]
        if len(csv_names) != 1:
            raise ValueError("Upload exactly one source CSV.")
        return Path(csv_names[0])
    raise FileNotFoundError(f"Could not find {expected_name!r}.")


def clean_display(value):
    '''Normalize whitespace/unicode so visually-identical strings compare equal.'''
    if pd.isna(value):
        return pd.NA
    text = unicodedata.normalize("NFKC", str(value)).replace(" ", " ")
    return re.sub(r"\s+", " ", text).strip()


def normalized_key(value):
    cleaned = clean_display(value)
    return pd.NA if pd.isna(cleaned) else cleaned.casefold()


pd.set_option("display.max_columns", 30)
pd.set_option("display.width", 140)
